@Test
@Transactional
void 주입_시도() {
    String column = "age) or (1=1";
    try {
        em.createQuery(
            "select m from Member m where m.age > 100 order by " + column,
            Member.class).getResultList();
    } catch (Exception e) {
        System.out.println("막힘: " + e.getClass().getSimpleName());
    }
}

