-- Sort 를 쓰면 검증된다

@Query("select m from Member m")
List<Member> all(Sort sort);

@Test
@Transactional
void sort_검증() {
    em.clear();
    memberRepository.all(Sort.by(Sort.Direction.DESC, "age"));

    try {
        memberRepository.all(Sort.by("age) or (1=1"));
    } catch (Exception e) {
        System.out.println("막힘: " + e.getClass().getSimpleName());
    }
}

